// =====================================================
// Clean + normalize + filter + dedupe
// Input:  raw Google Maps places from Apify
// Output: one clean row per unique company
// =====================================================

// ---------- helpers ----------

// Remove SEO keyword stuffing from Google titles
const cleanName = (t = "") => {
  let n = String(t).split("|")[0];                          // "PANDION SERVICE | Hausverwaltung Berlin" → "PANDION SERVICE"
  n = n.replace(/,\s*(Makler|Immobilienmakler).*$/i, "");    // "Galant ..., Makler, Immobilienmakler" → "Galant ..."
  return n.replace(/\s+/g, " ").trim();
};

// Reduce any URL to clean homepage + domain (regex, no URL object needed)
const cleanWebsite = (url) => {
  if (!url) return { website: "", domain: "" };
  const m = String(url).trim().match(/^(https?:\/\/)?([^\/?#:]+)/i);
  if (!m) return { website: String(url), domain: "" };
  const host = m[2].toLowerCase();
  const domain = host.replace(/^www\./, "");
  const protocol = (m[1] || "https://").toLowerCase();
  return { website: `${protocol}${host}/`, domain };
};

// Berlin postcode range check
const isBerlinPLZ = (plz) => {
  const p = parseInt(plz, 10);
  return !isNaN(p) && p >= 10115 && p <= 14199;
};

// Approximate postcode → district mapping (some postcodes cross borders)
const PLZ_RANGES = [
  [10115,10119,"Mitte"],[10178,10179,"Mitte"],[10551,10559,"Mitte"],[10785,10785,"Mitte"],[13347,13359,"Mitte"],
  [10243,10249,"Friedrichshain-Kreuzberg"],[10961,10999,"Friedrichshain-Kreuzberg"],
  [10405,10439,"Pankow"],[13086,13089,"Pankow"],[13125,13129,"Pankow"],[13156,13189,"Pankow"],
  [10315,10369,"Lichtenberg"],[13051,13059,"Lichtenberg"],
  [10585,10589,"Charlottenburg-Wilmersdorf"],[10623,10629,"Charlottenburg-Wilmersdorf"],
  [10707,10719,"Charlottenburg-Wilmersdorf"],[14050,14059,"Charlottenburg-Wilmersdorf"],
  [14193,14199,"Charlottenburg-Wilmersdorf"],[13627,13629,"Charlottenburg-Wilmersdorf"],
  [10777,10789,"Tempelhof-Schöneberg"],[10823,10829,"Tempelhof-Schöneberg"],[12099,12109,"Tempelhof-Schöneberg"],
  [12277,12279,"Tempelhof-Schöneberg"],[12305,12309,"Tempelhof-Schöneberg"],
  [12043,12059,"Neukölln"],[12347,12359,"Neukölln"],
  [12157,12169,"Steglitz-Zehlendorf"],[12203,12209,"Steglitz-Zehlendorf"],[12247,12249,"Steglitz-Zehlendorf"],
  [14109,14169,"Steglitz-Zehlendorf"],
  [12435,12459,"Treptow-Köpenick"],[12487,12489,"Treptow-Köpenick"],[12524,12527,"Treptow-Köpenick"],
  [12555,12559,"Treptow-Köpenick"],[12587,12589,"Treptow-Köpenick"],
  [12619,12689,"Marzahn-Hellersdorf"],
  [13403,13509,"Reinickendorf"],
  [13581,13599,"Spandau"],[14089,14089,"Spandau"],
];

// District: postcode first (reliable), Google neighborhood as fallback
const getDistrict = (plz, neighborhood) => {
  const p = parseInt(plz, 10);
  if (!isNaN(p)) {
    const hit = PLZ_RANGES.find(([a, b]) => p >= a && p <= b);
    if (hit) return hit[2];
  }
  return neighborhood ? String(neighborhood).replace(/^Bezirk\s+/i, "").trim() : "Unknown";
};

// Is this place in Berlin? Unknown location → keep (we only searched Berlin)
const inBerlin = (p) => {
  const city = (p.city || "").toLowerCase();
  if (city) return city.includes("berlin");
  if (p.postalCode) return isBerlinPLZ(p.postalCode);
  return true;
};

// ---------- normalize ----------
const raw = $input.all();

const rows = raw.map(({ json: p }) => {
  const { website, domain } = cleanWebsite(p.website);
  const name = cleanName(p.title);
  const cats = Array.isArray(p.categories) ? p.categories : [];
  return {
    place_id: p.placeId || "",
    company_name: name,
    generic_name: /^(haus|immobilien)verwaltung$/i.test(name) ? "yes" : "no",
    website,
    domain,
    street: p.street || "",
    postal_code: p.postalCode || "",
    district: getDistrict(p.postalCode, p.neighborhood),
    city: p.city || "Berlin",
    phone: p.phoneUnformatted || p.phone || "",
    google_category: p.categoryName || "",
    all_categories: cats.join(", "),
    broker_hint: cats.some(c => /makler|vermittlung|agentur/i.test(c)) ? "yes" : "no",
    google_rating: p.totalScore ?? "",
    google_reviews: p.reviewsCount ?? 0,
    maps_url: p.url || "",
    search_string: p.searchString || "",
    source: "Google Maps (Apify)",
    scraped_at: p.scrapedAt || new Date().toISOString(),
    status: website ? "new" : "no_website",
    _closed: p.permanentlyClosed === true,
    _berlin: inBerlin(p),
  };
});

// ---------- filter: open + in Berlin ----------
const kept = rows.filter(r => !r._closed && r._berlin);

// ---------- dedupe: place_id → domain → phone ----------
// Sort by reviews first, so the entry with the most reviews is the one kept
kept.sort((a, b) => (b.google_reviews || 0) - (a.google_reviews || 0));

const seen = new Set();
const unique = [];
for (const r of kept) {
  const keys = [
    r.place_id ? "pid:" + r.place_id : null,
    r.domain ? "dom:" + r.domain : null,
    r.phone ? "tel:" + r.phone.replace(/\D/g, "") : null,
  ].filter(Boolean);

  if (keys.some(k => seen.has(k))) continue;   // duplicate → skip
  keys.forEach(k => seen.add(k));

  delete r._closed;
  delete r._berlin;
  unique.push(r);
}

// ---------- funnel stats ----------
console.log(`Raw places: ${raw.length} | After filter: ${kept.length} | Unique companies: ${unique.length}`);

return unique.map(r => ({ json: r }));
